// Lightweight doughnut chart implementation for Chrome Extension
// (No external dependencies needed)

class Chart {
  constructor(ctx, config) {
    this.ctx = ctx;
    this.canvas = ctx.canvas;
    this.config = config;
    this.render();
  }

  destroy() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  }

  render() {
    const { data, options } = this.config;
    const dataset = data.datasets[0];
    const values = dataset.data;
    const colors = dataset.backgroundColor;
    const borderColors = dataset.borderColor;
    const labels = data.labels;
    const total = values.reduce((a, b) => a + b, 0);

    if (total === 0) return;

    const canvas = this.canvas;
    const ctx = this.ctx;
    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.parentElement.getBoundingClientRect();
    const size = Math.min(rect.width, rect.height) || 180;

    canvas.width = size * dpr;
    canvas.height = size * dpr;
    canvas.style.width = size + "px";
    canvas.style.height = size + "px";
    ctx.scale(dpr, dpr);

    const centerX = size / 2;
    const centerY = size / 2;
    const radius = size * 0.4;
    const cutout = options?.cutout
      ? (parseFloat(options.cutout) / 100) * radius
      : radius * 0.6;

    let startAngle = -Math.PI / 2;

    // Draw segments
    values.forEach((value, i) => {
      if (value === 0) return;
      const sliceAngle = (value / total) * 2 * Math.PI;

      ctx.beginPath();
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.arc(
        centerX,
        centerY,
        cutout,
        startAngle + sliceAngle,
        startAngle,
        true
      );
      ctx.closePath();
      ctx.fillStyle = colors[i];
      ctx.fill();

      if (borderColors && borderColors[i]) {
        ctx.strokeStyle = borderColors[i];
        ctx.lineWidth = dataset.borderWidth || 2;
        ctx.stroke();
      }

      // Draw percentage text on segment
      if (value / total > 0.08) {
        const midAngle = startAngle + sliceAngle / 2;
        const labelRadius = (radius + cutout) / 2;
        const textX = centerX + Math.cos(midAngle) * labelRadius;
        const textY = centerY + Math.sin(midAngle) * labelRadius;
        const pct = Math.round((value / total) * 100);

        ctx.fillStyle = "#fff";
        ctx.font = `bold ${Math.max(10, size * 0.07)}px sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(`${pct}%`, textX, textY);
      }

      startAngle += sliceAngle;
    });

    // Draw center text (total)
    ctx.fillStyle = "#e1e1e1";
    ctx.font = `bold ${Math.max(14, size * 0.1)}px sans-serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(total.toString(), centerX, centerY - 6);
    ctx.fillStyle = "#888";
    ctx.font = `${Math.max(9, size * 0.06)}px sans-serif`;
    ctx.fillText("komentar", centerX, centerY + 10);

    // Draw legend if enabled
    if (options?.plugins?.legend?.display !== false) {
      const legendY = size - 8;
      const legendFont = options?.plugins?.legend?.labels?.font?.size || 11;
      ctx.font = `${legendFont}px sans-serif`;
      ctx.textBaseline = "top";

      let legendX = centerX - 80;
      labels.forEach((label, i) => {
        if (i > 0) legendX += 60;
        // Color dot
        ctx.fillStyle = colors[i];
        ctx.beginPath();
        ctx.arc(legendX, legendY + 4, 4, 0, Math.PI * 2);
        ctx.fill();
        // Label
        ctx.fillStyle =
          options?.plugins?.legend?.labels?.color || "#aaa";
        ctx.textAlign = "left";
        ctx.fillText(label, legendX + 8, legendY);
      });
    }
  }
}

// Make it available globally
window.Chart = Chart;
